namespace Fanex.Razorbill.Module.ContextualCustomer.Services.Implement.ProfilePictures
{
    using System.Data;
    using System.Web;
    using Fanex.Common;
    using Fanex.Data;
    using Fanex.Razorbill.Module.ContextualCustomer.Criteria.ProfilePictures;
    using Fanex.Razorbill.Module.ContextualCustomer.Entities;
    using Fanex.Razorbill.Module.ContextualCustomer.Services.Interface;
    using Fanex.Razorbill.Module.ContextualCustomer.Utils;
    using Fanex.Razorbill.Module.ContextualCustomer.ViewModels;
    using Fanex.Razorbill.Module.Core.Extensions;

    /// <summary>
    /// Servicing of profile picture.
    /// </summary>
    public class ProfilePictureService : IProfilePictureService
    {
        /// <summary>
        /// Updating profile picture.
        /// </summary>
        /// <param name="profilePictureCriteria">Profile picture criteria.</param>
        /// <returns>Update result.</returns>
        public Result UpdatingAvatar(AvatarUpdatingCriteria profilePictureCriteria)
        {
            using (var objectDb = new ObjectDb(profilePictureCriteria.GetSettingKey()))
            {
                objectDb.ExecuteNonQuery(profilePictureCriteria.GetSpParams());

                var result  = new Result()
                {
                    ErrorCode = Converter.ToInt(objectDb.GetParameterValue("errcode")),
                    ErrorMessage = Converter.ToString2(objectDb.GetParameterValue("errmsg"))
                };

                if (result.ErrorCode == 0)
                {
                    result.ErrorMessage = profilePictureCriteria.IsDefaultAvatar ? ResourceExtension.GetResource("ProfilePicture", "DeleteSucessful") : ResourceExtension.GetResource("ProfilePicture", "Successful");
                    SessionExtension.BinaryAvatar = null;
                }

                return result;
            }
        }

        /// <summary>
        /// Select profile picture.
        /// </summary>
        /// <param name="custId">Customer Id.</param>
        /// <returns>Profile picture model.</returns>
        public ProfilePicture SelectingAvatar(int custId)
        {
            ProfilePicture avatar = new ProfilePicture();
            avatar.CustID = custId;
            AvatarSelectingCriteria avatarSelectingCriteria = new AvatarSelectingCriteria();
            avatarSelectingCriteria.CustId = custId;

            DataSet dataSet = new DataSet();
                using (var db = new ObjectDb(avatarSelectingCriteria.GetSettingKey()))
                {
                    var paramsOuput = avatarSelectingCriteria.GetSpParams();
                    dataSet = db.ExecuteDataSet(paramsOuput);
                }

                if (dataSet != null && dataSet.Tables.Count > 0 && dataSet.Tables[0].Rows.Count > 0)
                {
                    avatar.AvatarBinary = Converter.ToByteArray(dataSet.Tables[0].Rows[0]["image"]);
                    SessionExtension.IsDefaultAvatar = false;
                }
                else
                {
                    avatar.AvatarBinary = FileUpload.GetDefaultAvatar();
                    SessionExtension.IsDefaultAvatar = true;
                }

                SessionExtension.BinaryAvatar = avatar.AvatarBinary;

            return avatar;
        }
    }
}